<script setup lang="ts">
import { AlertTriangle, CalendarDays, Camera, Check, History, Mic, Save } from "lucide-vue-next";
import { ref } from "vue";
import type { DiagnosisResult } from "@/features/diagnosis/types/diagnosis-result";
import { saveDiagnosisFollowUp } from "@/services/diagnosis-history.service";
const props = defineProps<{ result: DiagnosisResult; sessionId?: string }>();
const state = ref("stable"); const note = ref(""); const saved = ref(false);
const states = [{ id: "better", label: "Amélioration" }, { id: "stable", label: "Stable" }, { id: "worse", label: "Aggravation" }];
async function save() { if (props.sessionId) await saveDiagnosisFollowUp({ sessionId: props.sessionId, evolution: state.value === "better" ? "improving" : state.value === "worse" ? "worsening" : "stable", extent: null, note: note.value, actionsCompleted: 0 }); saved.value = true; }
</script>
<template><section class="grid gap-4 lg:grid-cols-[1.15fr_.85fr]"><div class="space-y-4"><header class="section-head"><div><p class="eyebrow">SUIVI CONSEILLÉ</p><h2>Observez l’évolution dans {{ result.followUpDays }} jours</h2><p>Revenez ici pour comparer la situation et améliorer le conseil.</p></div><History class="size-8 text-primary" /></header><article class="card"><h2>Comment la situation évolue-t-elle ?</h2><div class="mt-3 grid grid-cols-3 gap-2"><button v-for="item in states" :key="item.id" class="state" :class="{ active: state === item.id }" @click="state=item.id">{{ item.label }}</button></div><label class="label">Ajouter une note<textarea v-model="note" rows="4" placeholder="Décrivez les changements observés…" /></label><div class="mt-3 flex flex-wrap gap-2"><button class="result-action"><Mic class="size-3.5" />Dicter</button><button class="result-action"><Camera class="size-3.5" />Ajouter une photo</button></div><button class="primary-btn" @click="save"><Save class="size-4" />{{ saved ? 'Observation enregistrée' : 'Enregistrer le suivi' }}</button></article></div><aside class="space-y-4"><article class="card"><h2>Points à vérifier</h2><ul class="checklist"><li v-for="x in result.followUpChecks" :key="x"><Check />{{ x }}</li></ul></article><article class="warning"><AlertTriangle class="size-5" /><div><b>Demandez un avis rapidement</b><p>Si l’état s’aggrave ou si une grande partie de la parcelle est touchée.</p></div></article><article class="card"><h2>Historique</h2><div class="source"><CalendarDays class="size-4" />Diagnostic initial · aujourd’hui</div></article></aside></section></template>
